// === Tab: mySketch ===
//Music by <a href="https://pixabay.com/users/lexin_music-28841948/?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=115667">Aleksey Chistilin</a> from <a href="https://pixabay.com/music//?utm_source=link-attribution&utm_medium=referral&utm_campaign=music&utm_content=115667">Pixabay</a>
//Attribution: KomaTebe

let f=0;
let W=900;
let counter=0
function preload() 
{
	soundFormats('mp3', "wav");//load music
  song = loadSound('https://openprocessing.org/sketch/2131201/files/spaceMusic.mp3');
}

setup=_=>
{
	createCanvas(1300, 700);
	pixelDensity(.45)
	song.play()
  amp = new p5.Amplitude();
	song.loop()
}
draw=_=>
{
	var vol = amp.getLevel();
  volumeLevel = round(map(vol, 0, 0.3,1, 50));
	frameRate(volumeLevel)
	counter++
  let r=W;
  background(volumeLevel/4);
  translate(1300/2,700/2);
  rotate(f/W);
  if(r>0)
	{
    for(z=255; z>=0; z-=2)
		{
			for(n=0;n<2;n++) //stars
				{
					fill(255)
					stroke(255)
					circle(random(-1300,1300),random(-700,700),random(1))
				}
      	for(i=0;i<TAU;i+=PI/32)
				{
					let n=noise(i,tan(i)/90000,(f+z)/100);
					push();
					rotate(i);
					strokeWeight( (volumeLevel/8.5) - random(3) )
					stroke(W-z);
					point(0,z*n);
					stroke(i+W,77);
					point(z-n*W,i*12);	
					pop();
					r--;
      	}
     }
   }
  f-=2;
}

